import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days NYC 2023- Data Security and Storage Hardening in Rook and Ceph","description":"","frontmatter":{"title":"Ceph Days NYC 2023- Data Security and Storage Hardening in Rook and Ceph","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","数据安全","存储加固","Rook","CephFS"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Data_Security_and_Storage_Hardening_in_Rook_and_Ceph.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Data_Security_and_Storage_Hardening_in_Rook_and_Ceph.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Days_NYC_2023_-_Data_Security_and_Storage_Hardening_in_Rook_and_Ceph.md"};function o(n,a,_,p,h,s){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议重点讨论了分布式存储系统 Ceph 的安全性，包括安全实践、威胁模型、加密实现以及产品安全管理等方面。会议主讲人为 Federico Lucifredi 和 Sage McTaggart，他们在 Ceph 和网络安全领域拥有丰富的经验。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>安全实践与威胁模型</strong></p><ul><li>强调了安全实践的重要性，特别是在针对特定基础设施点的加固。</li><li>讨论了在没有攻击者模型的情况下，单纯选择安全实践的不可行性。</li><li>提出了绝对安全的不现实性，强调了定义威胁模型的重要性。</li></ul></li><li><p><strong>网络安全区划分</strong></p><ul><li>介绍了四种网络安全区的划分：公共安全区、自客户端区、存储访问区和集群区。</li><li>讨论了各区域的安全需求和如何通过加密等手段保护数据传输。</li></ul></li><li><p><strong>产品安全管理</strong></p><ul><li>介绍了 IBM 的产品安全管理流程，包括安全开发生命周期、定期渗透测试、依赖项清单管理等。</li><li>强调了即使在 IBM，Ceph 的安全修复也会被回溯到上游，确保所有版本的 Ceph 都保持同等安全。</li></ul></li><li><p><strong>加密实现</strong></p><ul><li>讨论了服务器端和传输中的数据加密，特别是使用 LUKS 和 Ceph 协议的安全性。</li><li>介绍了对象存储网关的额外加密能力，包括用户密钥管理和 AWS SSE-KMS 支持。</li></ul></li><li><p><strong>身份与访问管理</strong></p><ul><li>讨论了使用共享密钥和 AES 加密的安全性，以及如何通过良好的实践来管理密钥和用户权限。</li></ul></li><li><p><strong>审计与数据保留</strong></p><ul><li>讨论了审计日志的重要性，以及如何在数据删除后确保数据不可恢复。</li><li>介绍了 RBD 的垃圾箱功能和 rgw 的版本控制功能，以及如何通过加密来实现安全删除。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续加强 Ceph 的安全性，特别是在 IBM 的新环境下，确保所有安全实践和流程都符合 IBM 的标准。</li><li>持续关注和改进 Ceph 的加密实现，特别是在数据传输和存储方面。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行定期的渗透测试和安全审查，确保 Ceph 的安全性。</li><li>与 IBM 的安全团队合作，进一步完善和扩展 Ceph 的安全流程。</li><li>持续关注和改进 Ceph 的身份和访问管理，确保用户数据的安全。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的所有安全实践和建议都旨在提高 Ceph 的安全性，特别是在面对不同威胁模型时。</li><li>会议还提到了一些外部资源，如 Kubernetes Secrets 管理、存储安全加固指南等，供进一步阅读和参考。</li></ul><p>本次会议为 Ceph 的安全性提供了一个全面的视角，并为未来的安全改进工作指明了方向。</p>',12)])])}const c=e(r,[["render",o]]);export{u as __pageData,c as default};
